// Custom Push Notification Service Worker
// This file is loaded alongside the Workbox service worker generated by vite-plugin-pwa

self.addEventListener("push", function (event) {
    if (!event.data) return;

    try {
        const data = event.data.json();
        const options = {
            body: data.body || "New update from Pitchside",
            icon: "/logo.png",
            badge: "/logo.png",
            vibrate: [100, 50, 100],
            data: {
                url: data.url || "/",
            },
            actions: data.actions || [],
        };

        event.waitUntil(
            self.registration.showNotification(data.title || "Pitchside", options)
        );
    } catch (e) {
        // Fallback for plain text push
        event.waitUntil(
            self.registration.showNotification("Pitchside", {
                body: event.data.text(),
                icon: "/logo.png",
            })
        );
    }
});

self.addEventListener("notificationclick", function (event) {
    event.notification.close();

    const url = event.notification.data?.url || "/";

    event.waitUntil(
        clients.matchAll({ type: "window", includeUncontrolled: true }).then(function (clientList) {
            // Focus an existing window if available
            for (const client of clientList) {
                if (client.url.includes(self.location.origin) && "focus" in client) {
                    client.navigate(url);
                    return client.focus();
                }
            }
            // Open a new window
            return clients.openWindow(url);
        })
    );
});
